package org.apache.commons.math3.dfp;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math3.FieldElement;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for Dfp.add(Dfp) method.
 * Aiming for high branch and line coverage.
 */
public class Dfp_add_TriageGen1Test {

    private DfpField field;

    @Before
    public void setUp() {
        // Assuming DfpField is accessible and can be instantiated for testing
        // In a real scenario, this would be initialized via a standard Dfp setup
        field = new DfpField(); 
    }

    @Test
    public void testAddDifferentRadixDigits() {
        Dfp a = new Dfp(field, 1.0);
        // Creating a mock or a different field instance if possible to trigger the radix check
        // Since field is usually immutable in properties, we simulate via a mock/subclass if needed
        // Here we assume a different field instance with different radix digits
        DfpField differentField = new DfpField() {
            @Override
            public int getRadixDigits() { return field.getRadixDigits() + 1; }
        };
        Dfp b = new Dfp(differentField, 1.0);

        Dfp result = a.add(b);
        Assert.assertTrue("Should result in NaN due to different radix", result.isNaN());
    }

    @Test
    public void testAddNaN() {
        Dfp a = new Dfp(field, 1.0);
        Dfp b = new Dfp(field, Double.NaN);

        Dfp result = a.add(b);
        Assert.assertTrue("NaN + finite should be NaN", result.isNaN());

        Dfp c = new Dfp(field, Double.NaN);
        Dfp result2 = c.add(a);
        Assert.assertTrue("finite + NaN should be NaN", result2.isNaN());
    }

    @Test
    public void testAddInfinite() {
        Dfp inf = new Dfp(field, Double.POSITIVE_INFINITY);
        Dfp negInf = new Dfp(field, Double.NEGATIVE_INFINITY);
        Dfp finite = new Dfp(field, 1.0);

        // Inf + Finite = Inf
        Assert.assertTrue(inf.add(finite).isInfinite());
        Assert.assertEquals(inf.toDouble(), inf.add(finite).toDouble(), 0.0);

        // Finite + Inf = Inf
        Assert.assertTrue(finite.add(inf).isInfinite());

        // Inf + Inf (same sign) = Inf
        Assert.assertTrue(inf.add(inf).isInfinite());

        // Inf + (-Inf) (different sign) = NaN (Invalid)
        Dfp result = inf.add(negInf);
        Assert.assertTrue("Inf + (-Inf) should be NaN", result.isNaN());
    }

    @Test
    public void testAddZero() {
        Dfp a = new Dfp(field, 5.0);
        Dfp zero = new Dfp(field, 0.0);
        Dfp negZero = new Dfp(field, -0.0);

        Assert.assertEquals(5.0, a.add(zero).toDouble(), 0.0);
        Assert.assertEquals(5.0, a.add(negZero).toDouble(), 0.0);

        Dfp zeroA = new Dfp(field, 0.0);
        Dfp zeroB = new Dfp(field, -0.0);
        Dfp resZero = zeroA.add(zeroB);
        // Per IEEE 854-1987 Section 6.3, adding 2 negative zeros results in positive zero
        Assert.assertTrue(resZero.isZero());
        Assert.assertEquals(0.0, resZero.toDouble(), 0.0);
    }

    @Test
    public void testAddNormal() {
        Dfp a = new Dfp(field, 10.5);
        Dfp b = new Dfp(field, 2.5);
        Dfp result = a.add(b);
        Assert.assertEquals(13.0, result.toDouble(), 0.0);

        Dfp c = new Dfp(field, -5.0);
        Dfp d = new Dfp(field, 2.0);
        Assert.assertEquals(-3.0, c.add(d).toDouble(), 0.0);
    }

    @Test
    public void testAddAlignmentAndCarry() {
        // Test alignment: one number much smaller than the other
        Dfp a = new Dfp(field, 1.0);
        Dfp b = new Dfp(field, 0.0000000001);
        Dfp result = a.add(b);
        Assert.assertEquals(a.toDouble() + b.toDouble(), result.toDouble(), 1e-15);

        // Test carry: 0.9 + 0.1 = 1.0
        Dfp c = new Dfp(field, 0.9);
        Dfp d = new Dfp(field, 0.1);
        Assert.assertEquals(1.0, c.add(d).toDouble(), 0.0000000001);
    }

    @Test
    public void testAddSubtractionEffect() {
        // Adding a negative number is subtraction
        Dfp a = new Dfp(field, 10.0);
        Dfp b = new Dfp(field, -3.0);
        Assert.assertEquals(7.0, a.add(b).toDouble(), 0.0);

        // Result sign should be that of the magnitude
        Dfp c = new Dfp(field, 3.0);
        Dfp d = new Dfp(field, -10.0);
        Assert.assertTrue(c.add(d).strictlyNegative());
        Assert.assertEquals(-7.0, c.add(d).toDouble(), 0.0);
    }

    @Test
    public void testOverflow() {
        // Use very large numbers to trigger overflow logic if the field allows
        // This is dependent on the DfpField implementation limits
        Dfp a = new Dfp(field, Double.MAX_VALUE);
        Dfp b = new Dfp(field, Double.MAX_VALUE);
        Dfp result = a.add(b);
        // If overflow occurs, it should either be Infinite or a trapped value
        Assert.assertTrue(result.isInfinite() || result.isNaN());
    }

    @Test
    public void testNormalization() {
        // Force a case where mantissa ends in zeros to trigger normalization loop
        Dfp a = new Dfp(field, 0.001);
        Dfp b = new Dfp(field, 0.001);
        Dfp result = a.add(b);
        Assert.assertEquals(0.002, result.toDouble(), 1e-10);
    }
}
